import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../l10n/l10n.dart';
import '../../notifications/show_flush_bar.dart';
import '../../providers/global/prefs_provider.dart';
import '../../providers/global/secure_store_provider.dart';
import '../../themes/stack_colors.dart';
import '../../utilities/assets.dart';
import '../../utilities/biometrics.dart';
import '../../utilities/flutter_secure_storage_interface.dart';
import '../../utilities/logger.dart';
import '../../utilities/text_styles.dart';
import '../../widgets/background.dart';
import '../../widgets/center_or_scroll.dart';
import '../../widgets/custom_buttons/app_bar_icon_button.dart';
import '../../widgets/custom_pin_put/custom_pin_put.dart';
import '../../widgets/loading_indicator.dart';
import '../home_view/home_view.dart';
import 'lock_screen_view.dart';

class CreatePinView extends ConsumerStatefulWidget {
  const CreatePinView({
    super.key,
    this.popOnSuccess = false,
    this.biometrics = const Biometrics(),
  });

  static const String routeName = "/createPin";

  final Biometrics biometrics;
  final bool popOnSuccess;

  @override
  ConsumerState<CreatePinView> createState() => _CreatePinViewState();
}

class _CreatePinViewState extends ConsumerState<CreatePinView> {
  BoxDecoration get _pinPutDecoration {
    return BoxDecoration(
      color: Theme.of(context).extension<StackColors>()!.infoItemIcons,
      border: Border.all(
        width: 1,
        color: Theme.of(context).extension<StackColors>()!.infoItemIcons,
      ),
      borderRadius: BorderRadius.circular(6),
    );
  }

  final PageController _pageController = PageController(
    initialPage: 0,
    keepPage: true,
  );

  // Attributes for Page 1 of the pageview
  final TextEditingController _pinPutController1 = TextEditingController();
  final FocusNode _pinPutFocusNode1 = FocusNode();

  // Attributes for Page 2 of the pageview
  final TextEditingController _pinPutController2 = TextEditingController();
  final FocusNode _pinPutFocusNode2 = FocusNode();

  late SecureStorageInterface _secureStore;
  late Biometrics biometrics;

  int pinCount = 1;

  /// The PIN matched and is being saved: the fingerprint check and the
  /// first secure storage write can take a second or two.
  bool _saving = false;

  @override
  initState() {
    _secureStore = ref.read(secureStoreProvider);
    biometrics = widget.biometrics;
    // On a fresh install the first secure storage access creates its
    // Keystore keys, which is slow on some phones: do it while the PIN is
    // typed rather than after.
    unawaited(
      _secureStore.read(key: kPinKey).then<void>((_) {}, onError: (_) {}),
    );

    super.initState();
  }

  @override
  void dispose() {
    _pageController.dispose();
    _pinPutController1.dispose();
    _pinPutController2.dispose();
    _pinPutFocusNode1.dispose();
    _pinPutFocusNode2.dispose();

    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Background(
      child: Scaffold(
        backgroundColor: Theme.of(context).extension<StackColors>()!.background,
        appBar: AppBar(
          leading: AppBarBackButton(
            onPressed: () async {
              if (_saving) return;
              if (FocusScope.of(context).hasFocus) {
                FocusScope.of(context).unfocus();
                await Future<void>.delayed(const Duration(milliseconds: 70));
              }
              if (mounted) {
                Navigator.of(context).pop(widget.popOnSuccess);
              }
            },
          ),
        ),
        body: SafeArea(
          child: Stack(
            children: [
              PageView(
                controller: _pageController,
                physics: const NeverScrollableScrollPhysics(),
                children: [
                  // page 1
                  CenterOrScroll(
                    child: Column(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        Text(
                          l10n.pinCreate,
                          style: STextStyles.pageTitleH1(context),
                        ),
                        const SizedBox(height: 8),
                        Text(
                          l10n.pinProtects,
                          style: STextStyles.subtitle(context),
                        ),
                        const SizedBox(height: 36),
                        CustomPinPut(
                          fieldsCount: pinCount,
                          eachFieldHeight: 12,
                          eachFieldWidth: 12,
                          textStyle: STextStyles.label(context)
                              .copyWith(fontSize: 1),
                          focusNode: _pinPutFocusNode1,
                          controller: _pinPutController1,
                          useNativeKeyboard: false,
                          obscureText: "",
                          inputDecoration: InputDecoration(
                            border: InputBorder.none,
                            enabledBorder: InputBorder.none,
                            focusedBorder: InputBorder.none,
                            disabledBorder: InputBorder.none,
                            errorBorder: InputBorder.none,
                            focusedErrorBorder: InputBorder.none,
                            fillColor: Theme.of(context)
                                .extension<StackColors>()!
                                .background,
                            counterText: "",
                          ),
                          isRandom: ref
                              .read(prefsChangeNotifierProvider)
                              .randomizePIN,
                          submittedFieldDecoration: _pinPutDecoration,
                          selectedFieldDecoration: _pinPutDecoration,
                          followingFieldDecoration: _pinPutDecoration,
                          onPinLengthChanged: (newLength) {
                            setState(() {
                              pinCount = newLength;
                            });
                          },
                          onSubmit: (String pin) {
                            if (pin.length < 4) {
                              showFloatingFlushBar(
                                type: FlushBarType.warning,
                                message: l10n.pinTooShort,
                                iconAsset: Assets.svg.alertCircle,
                                context: context,
                              );
                            } else {
                              _pageController.nextPage(
                                duration: const Duration(milliseconds: 300),
                                curve: Curves.linear,
                              );
                            }
                          },
                        ),
                      ],
                    ),
                  ),

                  // page 2
                  CenterOrScroll(
                    child: Column(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        Text(
                          l10n.pinConfirm,
                          style: STextStyles.pageTitleH1(context),
                        ),
                        const SizedBox(height: 8),
                        Text(
                          l10n.pinProtects,
                          style: STextStyles.subtitle(context),
                        ),
                        const SizedBox(height: 36),
                        CustomPinPut(
                          fieldsCount: pinCount,
                          eachFieldHeight: 12,
                          eachFieldWidth: 12,
                          textStyle: STextStyles.infoSmall(context).copyWith(
                            color: Theme.of(context)
                                .extension<StackColors>()!
                                .textSubtitle3,
                            fontSize: 1,
                          ),
                          focusNode: _pinPutFocusNode2,
                          controller: _pinPutController2,
                          useNativeKeyboard: false,
                          obscureText: "",
                          inputDecoration: InputDecoration(
                            border: InputBorder.none,
                            enabledBorder: InputBorder.none,
                            focusedBorder: InputBorder.none,
                            disabledBorder: InputBorder.none,
                            errorBorder: InputBorder.none,
                            focusedErrorBorder: InputBorder.none,
                            fillColor: Theme.of(context)
                                .extension<StackColors>()!
                                .background,
                            counterText: "",
                          ),
                          submittedFieldDecoration: _pinPutDecoration.copyWith(
                            color: Theme.of(context)
                                .extension<StackColors>()!
                                .infoItemIcons,
                            border: Border.all(
                              width: 1,
                              color: Theme.of(context)
                                  .extension<StackColors>()!
                                  .infoItemIcons,
                            ),
                          ),
                          selectedFieldDecoration: _pinPutDecoration,
                          followingFieldDecoration: _pinPutDecoration,
                          isRandom: ref
                              .read(prefsChangeNotifierProvider)
                              .randomizePIN,
                          onSubmit: (String pin) async {
                            if (_saving) return;
                            if (_pinPutController1.text ==
                                _pinPutController2.text) {
                              setState(() => _saving = true);
                              try {
                                // ask if want to use biometrics
                                final bool useBiometrics = await biometrics
                                    .authenticate(
                                      cancelButtonText: l10n.commonSkipCaps,
                                      localizedReason:
                                          l10n.pinFingerprintReason,
                                      title: l10n.pinFingerprintTitle,
                                    );

                                assert(
                                  ref
                                          .read(prefsChangeNotifierProvider)
                                          .hasPin ==
                                      false,
                                );

                                await _secureStore.write(
                                  key: kPinKey,
                                  value: pin,
                                );

                                ref
                                        .read(prefsChangeNotifierProvider)
                                        .useBiometrics =
                                    useBiometrics;
                                ref.read(prefsChangeNotifierProvider).hasPin =
                                    true;

                                await Future<void>.delayed(
                                  const Duration(milliseconds: 200),
                                );

                                if (context.mounted) {
                                  if (!widget.popOnSuccess) {
                                    unawaited(
                                      Navigator.of(context)
                                          .pushNamedAndRemoveUntil(
                                            HomeView.routeName,
                                            (route) => false,
                                          ),
                                    );
                                  } else {
                                    Navigator.of(context).pop();
                                  }
                                }
                              } catch (e, s) {
                                Logging.instance.e(
                                  "Saving the PIN failed",
                                  error: e,
                                  stackTrace: s,
                                );
                                if (context.mounted) {
                                  setState(() => _saving = false);
                                  _pinPutController2.text = '';
                                  unawaited(
                                    showFloatingFlushBar(
                                      type: FlushBarType.warning,
                                      message: l10n.pinSaveFailed,
                                      context: context,
                                      iconAsset: Assets.svg.alertCircle,
                                    ),
                                  );
                                }
                              }
                            } else {
                              unawaited(
                                _pageController.animateTo(
                                  0,
                                  duration: const Duration(milliseconds: 300),
                                  curve: Curves.linear,
                                ),
                              );

                              unawaited(
                                showFloatingFlushBar(
                                  type: FlushBarType.warning,
                                  message: l10n.pinMismatch,
                                  context: context,
                                  iconAsset: Assets.svg.alertCircle,
                                ),
                              );

                              _pinPutController1.text = '';
                              _pinPutController2.text = '';
                            }
                          },
                        ),
                      ],
                    ),
                  ),
                ],
              ),
              if (_saving)
                Positioned.fill(
                  child: AbsorbPointer(
                    child: ColoredBox(
                      color: Theme.of(context)
                          .extension<StackColors>()!
                          .background
                          .withValues(alpha: 0.9),
                      child: Column(
                        mainAxisAlignment: MainAxisAlignment.center,
                        children: [
                          const LoadingIndicator(width: 100, height: 100),
                          const SizedBox(height: 16),
                          Text(
                            l10n.pinSaving,
                            style: STextStyles.subtitle(context),
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
            ],
          ),
        ),
      ),
    );
  }
}
